Method Handlers
const name = ref('Vue.js')
function greet(event) {
alert(`Hello ${name.value}!`)
// `event` is the native DOM event
if (event) {
console.log(event.target.tagName) //BUTTON
console.log(event.target.name) //greetBtn
console.log(event.target.id) //greetId
}
}
<!-- `greet` is the name of the method defined above -->
<button @click="greet" name="greetBtn" id= "greetId" >Greet</button>

watch()
<script>
const searchTodoId = ref(1)
const todoResult = ref('')
watch(
searchTodoId,
async () => {
try {
const res = await fetch(
`http://localhost:3000/todo/${searchTodoId.value}`
)
todoResult.value = await res.json()
console.log(todoResult.value)
} catch (e) {
console.log(e)
}
},
{
immediate: true
}
)
</script>
<template>
<div>
Your search todo id: <input type="number“ v-model="searchTodoId" />
<div>
<p>Your search result:</p>
<p>{{ todoResult }}</p>
</div>
</div>
</template>
